const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  // desktop: click opens toast
  const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });
  await page.goto('http://localhost:5188/community', { waitUntil: 'networkidle' });
  await page.evaluate(() => document.documentElement.classList.add('dark'));
  await page.evaluate(() => document.querySelector('.cm-newsletter-btn')?.scrollIntoView({ block: 'center' }));
  await page.waitForTimeout(300);
  await page.screenshot({ path: '$S/cm-btn.png', clip: { x: 300, y: 200, width: 760, height: 460 } });
  await page.click('.cm-newsletter-btn');
  await page.waitForTimeout(600);
  const toastOpen = await page.evaluate(() => Boolean(document.querySelector('.newsletter--toast')));
  console.log('desktop toast opened:', toastOpen);
  await page.close();
  // mobile: click scrolls to in-flow form
  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await mobile.goto('http://localhost:5188/community', { waitUntil: 'networkidle' });
  await mobile.evaluate(() => document.documentElement.classList.add('dark'));
  await mobile.evaluate(() => document.querySelector('.cm-newsletter-btn')?.click());
  await mobile.waitForTimeout(1200);
  const scrolled = await mobile.evaluate(() => {
    const form = document.querySelector('.newsletter--cta');
    if (!form) return 'no cta form';
    const rect = form.getBoundingClientRect();
    return rect.top >= 0 && rect.top < window.innerHeight ? 'form in viewport' : 'not visible: ' + Math.round(rect.top);
  });
  console.log('mobile:', scrolled);
  await browser.close();
})();
"
